using System;
using System.Collections.Generic;

namespace Draftmaster.MasterDraft
{
    // ---- Challenges.json --------------------------------------------------------------------------------------
    // Generated by Tools/masterdraft_export.py from Draftmaster 2's Assets/Scripts/EventData.cs; edit the C# (or the
    // script's tables) and re-run rather than hand-editing the JSON. Public fields for JsonUtility.

    // A historic "moment" a chapter replays: the race joins on startingLap with the grid in fieldOrder. All empty for
    // a chapter that is an ordinary race.
    [Serializable]
    public class ChallengeMoment
    {
        public string name;          // DM2 MomentsCriteria set ("Atlanta01"): the win conditions, ported later
        public int startingLap;      // the race starts on this lap; 0 = from the green
        public List<string> fieldOrder = new List<string>();   // grid slots front to back, two per row: car number, "player", or "x" (empty)
        public string carset;        // the field's carset ("cup01"); "" = the player's car's carset
        public string field;         // DM2 roster name for the field ("cup01MomentsAtlanta")
        public string playerLivery;  // the car the player is handed ("cup01livery29"); "" = choose from the garage
        public string modifier;      // DM2 race modifier ("delicate", "wallride")

        public const string PlayerSlot = "player";
        public const string EmptySlot = "x";

        public bool HasFieldOrder => fieldOrder != null && fieldOrder.Count > 0;
        public bool ProvidesCar => !string.IsNullOrEmpty(playerLivery);
    }

    // What a chapter's prize is (ChallengePrize.kind).
    public static class ChallengePrizeKind
    {
        public const string None = "";
        public const string Car = "Car";            // one of cars (a named driver's car: "Johnson" -> cup20_48)
        public const string Category = "Category";  // a car drawn from the catalogue by filter (Rookies, 1Star, HEN...)
        public const string AltPaint = "AltPaint";  // the alternate livery sprite in livery, for cars[0]
    }

    [Serializable]
    public class ChallengePrize
    {
        public string kind;           // ChallengePrizeKind
        public string code;           // DM2 offlinePrizes ("Johnson", "1Star", "AltPaint")
        public List<string> cars = new List<string>();   // Car: the cars it can be (usually one); AltPaint: the car it paints
        public int gears;             // DM2 offlineSetPrizes for car prizes; 0 = Challenges' defaults
        public string livery;         // AltPaint: Resources sprite, "cup20livery48alt1"
        public PrizeFilter filter = new PrizeFilter();   // Category

        public bool IsNone => string.IsNullOrEmpty(kind);
    }

    // One race of an event.
    [Serializable]
    public class ChallengeChapter
    {
        public string id;             // "{event}_{name}" slug, "ol_seven_time_daytona"
        public string eventId;
        public int[] dm2Index;        // [event, chapter] in DM2's arrays
        public string name;
        public string description;
        public string image;          // Resources sprite: a livery or DM2 track art
        public int aiLevel;
        public Restriction restriction = new Restriction();
        public string track;          // TrackCatalog id
        public int dm2Track;
        public int baseLaps;          // DM2's base laps at the track (for chapters with no raceLaps)
        public int raceLaps;          // the race's full length; 0 = SeriesRules.RaceLaps(baseLaps, aiLevel)
        public ChallengeMoment moment = new ChallengeMoment();
        public ChallengePrize prize = new ChallengePrize();

        // The player races the car the chapter hands them, not one from the garage.
        public bool ProvidesCar => moment != null && moment.ProvidesCar;

        public override string ToString() => $"{id} ({track}, ai {aiLevel}, {restriction})";
    }

    public static class ChallengeEventType
    {
        public const string Progression = "Progression";  // chapters unlock in order; each prize is paid once
        public const string Replay = "Replay";            // every chapter open; the prize is paid every completion
    }

    // A top-level tile ("Ol' Seven-Time") and its chapters in order.
    [Serializable]
    public class ChallengeEvent
    {
        public string id;
        public int dm2Index;
        public string name;
        public string type;           // ChallengeEventType
        public List<int> weeks = new List<int>();   // weeks of the cycle it runs, 1-based
        public string description;
        public string image;
        public List<ChallengeChapter> chapters = new List<ChallengeChapter>();

        public bool IsProgression => type == ChallengeEventType.Progression;

        // By id, so a chapter from another load of the same file still finds its place.
        public int IndexOf(ChallengeChapter chapter)
        {
            if (chapters == null || chapter == null) return -1;
            for (int i = 0; i < chapters.Count; i++)
                if (chapters[i] != null && chapters[i].id == chapter.id) return i;
            return -1;
        }
    }

    [Serializable]
    public class ChallengesFile
    {
        public int version;
        public string source;
        public int cycleWeeks;
        public List<ChallengeEvent> events = new List<ChallengeEvent>();
    }

    // Every event and chapter. Engine-free: the runtime hands FromJson the TextAsset at ResourcePath.
    public class ChallengeCatalog
    {
        public const string ResourcePath = "MasterDraft/Challenges";   // Resources.Load<TextAsset>(ResourcePath)

        readonly List<ChallengeEvent> events = new List<ChallengeEvent>();
        readonly Dictionary<string, ChallengeEvent> eventsById = new Dictionary<string, ChallengeEvent>(StringComparer.Ordinal);
        readonly Dictionary<string, ChallengeChapter> chaptersById = new Dictionary<string, ChallengeChapter>(StringComparer.Ordinal);

        public int Version { get; }
        public int CycleWeeks { get; } = Challenges.DefaultCycleWeeks;
        public IReadOnlyList<ChallengeEvent> Events => events;

        // Chapters with no id or no track are dropped (nothing to race), as are events left with none; a repeated id
        // keeps its first row. Missing nested objects become empty ones.
        public ChallengeCatalog(ChallengesFile file)
        {
            if (file == null) return;
            Version = file.version;
            if (file.cycleWeeks > 0) CycleWeeks = file.cycleWeeks;
            if (file.events == null) return;
            foreach (var e in file.events)
            {
                if (e == null || string.IsNullOrEmpty(e.id) || eventsById.ContainsKey(e.id)) continue;
                if (e.weeks == null) e.weeks = new List<int>();
                var kept = new List<ChallengeChapter>();
                if (e.chapters != null)
                    foreach (var c in e.chapters)
                    {
                        if (c == null || string.IsNullOrEmpty(c.id) || string.IsNullOrEmpty(c.track) || chaptersById.ContainsKey(c.id)) continue;
                        if (c.restriction == null) c.restriction = new Restriction();
                        if (c.moment == null) c.moment = new ChallengeMoment();
                        if (c.moment.fieldOrder == null) c.moment.fieldOrder = new List<string>();
                        if (c.prize == null) c.prize = new ChallengePrize();
                        if (c.prize.cars == null) c.prize.cars = new List<string>();
                        if (c.prize.filter == null) c.prize.filter = new PrizeFilter();
                        if (string.IsNullOrEmpty(c.eventId)) c.eventId = e.id;
                        kept.Add(c);
                        chaptersById[c.id] = c;
                    }
                e.chapters = kept;
                if (kept.Count == 0) continue;
                events.Add(e);
                eventsById[e.id] = e;
            }
        }

        public static ChallengeCatalog FromJson(string json)
        {
            if (string.IsNullOrWhiteSpace(json)) return null;
            var read = ProfileJson.Reader;
            ChallengesFile file;
            try { file = read(json, typeof(ChallengesFile)) as ChallengesFile; }
            catch (Exception) { return null; }
            return file == null ? null : new ChallengeCatalog(file);
        }

        public ChallengeEvent Get(string eventId) => eventId != null && eventsById.TryGetValue(eventId, out var e) ? e : null;

        public ChallengeChapter GetChapter(string chapterId) =>
            chapterId != null && chaptersById.TryGetValue(chapterId, out var c) ? c : null;

        public ChallengeEvent EventOf(ChallengeChapter chapter) => chapter == null ? null : Get(chapter.eventId);
    }

    // ---- Progress -----------------------------------------------------------------------------------------------

    // One chapter's history in the profile (DM2's BestFinishPosition{event}{chapter}EVENT1 PlayerPrefs, plus what
    // DM2 left implicit).
    [Serializable]
    public class ChallengeRecord
    {
        public string chapterId;
        public int attempts;          // races finished (any result)
        public int completions;       // races won, or moment conditions met
        public int bestFinish;        // 1-based; 0 = none yet
        public int prizesPaid;        // prizes claimed: at most 1 for a Progression chapter, one per completion for Replay

        public bool Completed => completions > 0;
        public bool PrizeCollected => prizesPaid > 0;

        public override string ToString() => $"{chapterId}: {completions}/{attempts} best P{bestFinish}, {prizesPaid} prizes";
    }

    // Why a chapter can't be raced right now. Restriction failures sit in ChallengeEntry.restriction.
    public enum ChallengeLock
    {
        NotLive = 0,          // the event doesn't run this week
        ChapterLocked = 1,    // a Progression event's previous chapter isn't completed
        Restriction = 2,      // the car / level don't meet the chapter's entry requirements
    }

    public class ChallengeEntry
    {
        public bool live;
        public bool chapterUnlocked;
        public Eligibility restriction = new Eligibility();

        public bool Eligible => live && chapterUnlocked && restriction.Eligible;

        public List<ChallengeLock> Locks
        {
            get
            {
                var list = new List<ChallengeLock>();
                if (!live) list.Add(ChallengeLock.NotLive);
                if (!chapterUnlocked) list.Add(ChallengeLock.ChapterLocked);
                if (!restriction.Eligible) list.Add(ChallengeLock.Restriction);
                return list;
            }
        }

        // One line per reason, event-level first, for a locked tile.
        public string Summary
        {
            get
            {
                if (Eligible) return "Eligible";
                var lines = new List<string>();
                if (!live) lines.Add("Not running this week");
                if (!chapterUnlocked) lines.Add("Win the previous chapter first");
                foreach (var r in restriction.Reasons) lines.Add(r.message);
                return string.Join("\n", lines);
            }
        }

        public override string ToString() => Summary;
    }

    // What finishing a chapter race did.
    public struct ChallengeResult
    {
        public bool completed;         // won, or the moment's conditions were met
        public bool firstCompletion;
        public bool prizeDue;          // pay the prize now (ClaimPrize)
    }

    // An event's chapters done, for the tile ("3/8").
    public struct EventProgress
    {
        public int completed;
        public int total;
        public int nextChapter;        // index of the first chapter not completed; total when all are

        public bool IsFinished => total > 0 && completed >= total;
    }

    // What a prize turned into. Resolve first (pure, for the reveal), then Apply.
    public class PrizeOutcome
    {
        public string kind = ChallengePrizeKind.None;   // ChallengePrizeKind; None when nothing is paid
        public string carId;           // the car won (Car / Category) or painted (AltPaint)
        public int gears;              // gears that land on the car
        public bool newCar;            // the car wasn't in the garage: it arrives at class 0 holding gears
        public string livery;          // AltPaint
        public bool duplicateAltPaint; // AltPaint already unlocked: nothing is paid (DM2 "Duplicate Alt Found!")
        public bool emptyPool;         // a car prize with no car to give (data or catalogue gap)

        public bool PaysSomething => kind != ChallengePrizeKind.None && !duplicateAltPaint && !emptyPool;

        public override string ToString() =>
            !PaysSomething ? (duplicateAltPaint ? $"duplicate {livery}" : emptyPool ? "empty prize pool" : "no prize")
            : kind == ChallengePrizeKind.AltPaint ? $"alt paint {livery}"
            : newCar ? $"new car {carId} ({gears} gears)" : $"{carId} +{gears} gears";
    }

    // Draftmaster 2's challenges ("Events"), ported from EventsUI / EventUIFunctions / RaceRewardsUI / PrizeCollection
    // (git show 2217821d^:Assets/Scripts/UI/EventsUI.cs and friends) onto Master Draft's catalogue and garage:
    //
    //  - The game runs a 13-week cycle (GameData: the week wraps after 13). An event is live in the weeks it lists;
    //    otherwise its tile is covered. DM2 tested the week with a substring match, so week 12 also lit events listed
    //    for week 1 or 2; here the week must be listed exactly.
    //  - Progression events open chapter by chapter: the first is always open, each later one once the one before
    //    it is completed (EventsUI.loadSubEvent). Replay events have every chapter open.
    //  - A chapter's entry requirements go through the shared Restrictions engine. A chapter that hands the player a
    //    car (moment.playerLivery) skips the garage — DM2 went straight past it (GarageUI.autoSelectCar) — so only
    //    the player-level requirement applies.
    //  - A chapter is completed by winning, or by meeting a moment's conditions (DM2 MomentComplete). A Progression
    //    chapter pays its prize once; a Replay chapter pays every completion (DM2 hid the prize of a won
    //    Progression chapter and paid it only once).
    //  - Prizes: a named driver's car (Car) or a car drawn with a seed from a catalogue filter (Category; DM2's
    //    ListRewards pool, skipping class-6 cars like RaceRewardsUI did unless every car is class 6). A car you
    //    don't own arrives at class 0 with the set gears, at least CarProgression.StarterGears; one you own gets
    //    the set gears, or CarProgression.DuplicateGears when the chapter sets none. An AltPaint prize unlocks that
    //    livery once; a duplicate pays nothing.
    public static class Challenges
    {
        public const int DefaultCycleWeeks = 13;

        // --- Weeks -------------------------------------------------------------------------------------------

        // Any week number (1, 2, ... forever) -> its week of the cycle, 1..cycleWeeks.
        public static int CycleWeek(int week, int cycleWeeks = DefaultCycleWeeks)
        {
            if (cycleWeeks <= 0) cycleWeeks = DefaultCycleWeeks;
            int w = (week - 1) % cycleWeeks;
            if (w < 0) w += cycleWeeks;
            return w + 1;
        }

        // Days since the profile started (0 = the first day) -> the week of the cycle. DM2 counted 7 game days a week.
        public static int WeekForDay(int daysSinceStart, int cycleWeeks = DefaultCycleWeeks) =>
            CycleWeek(Math.Max(0, daysSinceStart) / 7 + 1, cycleWeeks);

        public static bool IsLive(ChallengeEvent ev, int week, int cycleWeeks = DefaultCycleWeeks) =>
            ev?.weeks != null && ev.weeks.Contains(CycleWeek(week, cycleWeeks));

        // The events running this week, in catalogue order.
        public static List<ChallengeEvent> LiveEvents(ChallengeCatalog catalog, int week)
        {
            var list = new List<ChallengeEvent>();
            if (catalog == null) return list;
            foreach (var e in catalog.Events) if (IsLive(e, week, catalog.CycleWeeks)) list.Add(e);
            return list;
        }

        // Weeks until the event next runs: 0 when live now, -1 when it never runs.
        public static int WeeksUntilLive(ChallengeEvent ev, int week, int cycleWeeks = DefaultCycleWeeks)
        {
            if (ev?.weeks == null || ev.weeks.Count == 0) return -1;
            if (cycleWeeks <= 0) cycleWeeks = DefaultCycleWeeks;
            for (int ahead = 0; ahead < cycleWeeks; ahead++)
                if (ev.weeks.Contains(CycleWeek(week + ahead, cycleWeeks))) return ahead;
            return -1;
        }

        // --- Progress ----------------------------------------------------------------------------------------

        public static ChallengeRecord FindRecord(IList<ChallengeRecord> records, string chapterId)
        {
            if (records == null || string.IsNullOrEmpty(chapterId)) return null;
            foreach (var r in records) if (r != null && r.chapterId == chapterId) return r;
            return null;
        }

        public static ChallengeRecord GetOrAddRecord(IList<ChallengeRecord> records, string chapterId)
        {
            if (records == null) throw new ArgumentNullException(nameof(records));
            if (string.IsNullOrEmpty(chapterId)) throw new ArgumentException("chapter id required", nameof(chapterId));
            var r = FindRecord(records, chapterId);
            if (r == null) records.Add(r = new ChallengeRecord { chapterId = chapterId });
            return r;
        }

        public static bool IsCompleted(IList<ChallengeRecord> records, string chapterId)
        {
            var r = FindRecord(records, chapterId);
            return r != null && r.Completed;
        }

        // Progression: the first chapter is open, each later one once the previous is completed. Replay: all open.
        public static bool ChapterUnlocked(ChallengeEvent ev, int chapterIndex, IList<ChallengeRecord> records)
        {
            if (ev?.chapters == null || chapterIndex < 0 || chapterIndex >= ev.chapters.Count) return false;
            if (!ev.IsProgression || chapterIndex == 0) return true;
            return IsCompleted(records, ev.chapters[chapterIndex - 1].id);
        }

        public static bool ChapterUnlocked(ChallengeEvent ev, ChallengeChapter chapter, IList<ChallengeRecord> records) =>
            ChapterUnlocked(ev, ev == null ? -1 : ev.IndexOf(chapter), records);

        public static EventProgress Progress(ChallengeEvent ev, IList<ChallengeRecord> records)
        {
            var p = new EventProgress();
            if (ev?.chapters == null) return p;
            p.total = ev.chapters.Count;
            p.nextChapter = p.total;
            for (int i = 0; i < ev.chapters.Count; i++)
            {
                if (IsCompleted(records, ev.chapters[i].id)) p.completed++;
                else if (p.nextChapter == p.total) p.nextChapter = i;
            }
            return p;
        }

        // A Progression chapter completed but its prize never paid (DM2's "Unclaimed Rewards Collected").
        public static bool HasUnclaimedPrize(ChallengeEvent ev, ChallengeChapter chapter, IList<ChallengeRecord> records)
        {
            if (ev == null || chapter == null || chapter.prize == null || chapter.prize.IsNone || !ev.IsProgression) return false;
            var r = FindRecord(records, chapter.id);
            return r != null && r.Completed && !r.PrizeCollected;
        }

        // Prizes completed but not yet claimed: Progression 0 or 1, Replay one per unclaimed completion.
        public static int PrizesOwed(ChallengeEvent ev, ChallengeChapter chapter, IList<ChallengeRecord> records)
        {
            if (chapter == null || chapter.prize == null || chapter.prize.IsNone) return 0;
            var r = FindRecord(records, chapter.id);
            if (r == null || !r.Completed) return 0;
            bool replay = ev != null && !ev.IsProgression;
            return replay ? Math.Max(0, r.completions - r.prizesPaid) : (r.prizesPaid == 0 ? 1 : 0);
        }

        // --- Entering ----------------------------------------------------------------------------------------

        // Can the player race this chapter now, in this car? car / garage are ignored when the chapter hands the
        // player a car.
        public static ChallengeEntry CanEnter(ChallengeEvent ev, ChallengeChapter chapter, CarDef car, IList<OwnedCar> garage,
            int playerLevel, int week, IList<ChallengeRecord> records, int cycleWeeks = DefaultCycleWeeks)
        {
            var entry = new ChallengeEntry
            {
                live = IsLive(ev, week, cycleWeeks),
                chapterUnlocked = ChapterUnlocked(ev, chapter, records),
            };
            if (chapter == null)
            {
                entry.restriction.Add(RestrictionFailure.NoCar, "No such chapter");
                return entry;
            }
            if (chapter.ProvidesCar)
            {
                var r = chapter.restriction ?? new Restriction();
                if (playerLevel < r.minLevel)
                    entry.restriction.Add(RestrictionFailure.PlayerLevel, $"Reach level {r.minLevel} (you're level {playerLevel})");
            }
            else
            {
                entry.restriction = Restrictions.CheckInGarage(chapter.restriction, car, garage, playerLevel);
            }
            return entry;
        }

        // The car id of the car a chapter hands the player ("cup22livery1" -> "cup22_1"), or null. It may not be in
        // the catalogue: DM2's moments use carsets that can't be won (cup01, cup79, dm2se...).
        public static string ProvidedCarId(ChallengeChapter chapter)
        {
            if (chapter == null || !chapter.ProvidesCar) return null;
            string livery = chapter.moment.playerLivery;
            int at = livery.LastIndexOf("livery", StringComparison.Ordinal);
            if (at <= 0 || !int.TryParse(livery.Substring(at + "livery".Length), out int number)) return null;
            return CarCatalog.IdFor(livery.Substring(0, at), number);
        }

        // --- The race ----------------------------------------------------------------------------------------

        // The race's full length: the chapter's own, else the series formula on the track's base laps.
        public static int RaceLaps(ChallengeChapter chapter, int customMultiplier = 0)
        {
            if (chapter == null) return 0;
            if (chapter.raceLaps > 0) return chapter.raceLaps;
            return SeriesRules.RaceLaps(chapter.baseLaps, chapter.aiLevel, customMultiplier);
        }

        // The lap the race starts on, 1 for a race from the green; never past the last lap.
        public static int StartingLap(ChallengeChapter chapter, int customMultiplier = 0)
        {
            int laps = RaceLaps(chapter, customMultiplier);
            int start = chapter?.moment == null ? 1 : Math.Max(1, chapter.moment.startingLap);
            return Math.Max(1, Math.Min(laps, start));
        }

        // Laps the player actually drives (the starting lap through the last).
        public static int LapsToRun(ChallengeChapter chapter, int customMultiplier = 0)
        {
            if (chapter == null) return 0;
            return RaceLaps(chapter, customMultiplier) - StartingLap(chapter, customMultiplier) + 1;
        }

        // A grid slot of a moment's field order.
        public struct GridSlot
        {
            public int slot;      // 0-based, front to back; row = slot / 2
            public int number;    // car number in the field's carset

            public override string ToString() => $"slot {slot}: #{number}";
        }

        // The player's 0-based grid slot in a moment's field order; -1 when the chapter sets none.
        public static int PlayerGridSlot(ChallengeMoment moment) =>
            moment?.fieldOrder == null ? -1 : moment.fieldOrder.IndexOf(ChallengeMoment.PlayerSlot);

        // The AI cars a moment places, in grid order ("x" slots are empty, so slots skip).
        public static List<GridSlot> GridCars(ChallengeMoment moment)
        {
            var list = new List<GridSlot>();
            if (moment?.fieldOrder == null) return list;
            for (int i = 0; i < moment.fieldOrder.Count; i++)
                if (int.TryParse(moment.fieldOrder[i], out int number))
                    list.Add(new GridSlot { slot = i, number = number });
            return list;
        }

        // Fold a finished chapter race into the records. finishPosition is 1-based (0 = not classified);
        // momentComplete = the moment's conditions were met whatever the position.
        public static ChallengeResult RecordResult(IList<ChallengeRecord> records, ChallengeEvent ev, ChallengeChapter chapter,
            int finishPosition, bool momentComplete = false)
        {
            if (records == null) throw new ArgumentNullException(nameof(records));
            if (chapter == null) throw new ArgumentNullException(nameof(chapter));
            var r = GetOrAddRecord(records, chapter.id);
            var result = new ChallengeResult { completed = finishPosition == 1 || momentComplete };
            r.attempts++;
            if (finishPosition > 0 && (r.bestFinish == 0 || finishPosition < r.bestFinish)) r.bestFinish = finishPosition;
            if (result.completed)
            {
                result.firstCompletion = r.completions == 0;
                r.completions++;
                bool hasPrize = chapter.prize != null && !chapter.prize.IsNone;
                bool replay = ev != null && !ev.IsProgression;
                result.prizeDue = hasPrize && (replay || r.prizesPaid == 0);
            }
            return result;
        }

        // --- Prizes ------------------------------------------------------------------------------------------

        // Every car the prize could be (DM2 EventData.ListRewards, for the rewards popup), in catalogue order.
        public static List<CarDef> PrizePool(ChallengePrize prize, CarCatalog catalog)
        {
            var list = new List<CarDef>();
            if (prize == null || catalog == null) return list;
            switch (prize.kind)
            {
                case ChallengePrizeKind.Car:
                case ChallengePrizeKind.AltPaint:
                    if (prize.cars != null)
                        foreach (var id in prize.cars)
                        {
                            var c = catalog.Get(id);
                            if (c != null && !list.Contains(c)) list.Add(c);
                        }
                    break;
                case ChallengePrizeKind.Category:
                    if (prize.filter != null)
                        foreach (var c in catalog.Cars) if (Matches(prize.filter, c)) list.Add(c);
                    break;
            }
            return list;
        }

        // A stable seed for one prize draw: the profile's seed, the chapter and which completion this is, so a
        // replayed reveal draws the same car and the next completion a fresh one.
        public static long PrizeSeed(long profileSeed, string chapterId, int completion) =>
            unchecked(profileSeed * 31 + DraftRng.Hash(chapterId) * 17 + completion);

        // Decide what the prize pays, without touching the garage. altPaints = the livery sprites already unlocked.
        public static PrizeOutcome ResolvePrize(ChallengePrize prize, CarCatalog catalog, IList<OwnedCar> garage,
            ICollection<string> altPaints, long seed)
        {
            var o = new PrizeOutcome();
            if (prize == null || prize.IsNone) return o;
            o.kind = prize.kind;
            switch (prize.kind)
            {
                case ChallengePrizeKind.AltPaint:
                    o.livery = prize.livery;
                    o.carId = prize.cars != null && prize.cars.Count > 0 ? prize.cars[0] : null;
                    if (string.IsNullOrEmpty(prize.livery)) o.emptyPool = true;
                    else if (altPaints != null && altPaints.Contains(prize.livery)) o.duplicateAltPaint = true;
                    return o;
                case ChallengePrizeKind.Car:
                case ChallengePrizeKind.Category:
                    var pool = PrizePool(prize, catalog);
                    if (pool.Count == 0)
                    {
                        o.emptyPool = true;
                        return o;
                    }
                    // RaceRewardsUI skipped class-6 cars (nothing left to fill); keep the full pool if that's all there is.
                    var open = pool.FindAll(c => !CarProgression.IsMaxClass(CarProgression.Find(garage, c.id)));
                    if (open.Count == 0) open = pool;
                    var car = new DraftRng(seed).Pick(open);
                    o.carId = car.id;
                    o.newCar = !CarProgression.Owns(garage, car.id);
                    o.gears = o.newCar
                        ? Math.Max(CarProgression.StarterGears, prize.gears)
                        : (prize.gears > 0 ? prize.gears : CarProgression.DuplicateGears);
                    return o;
                default:
                    o.kind = ChallengePrizeKind.None;
                    return o;
            }
        }

        // Pay a resolved prize into the garage / unlocked liveries.
        public static void ApplyPrize(PrizeOutcome outcome, IList<OwnedCar> garage, ICollection<string> altPaints)
        {
            if (outcome == null || !outcome.PaysSomething) return;
            switch (outcome.kind)
            {
                case ChallengePrizeKind.AltPaint:
                    if (altPaints == null) throw new ArgumentNullException(nameof(altPaints));
                    if (!altPaints.Contains(outcome.livery)) altPaints.Add(outcome.livery);
                    break;
                case ChallengePrizeKind.Car:
                case ChallengePrizeKind.Category:
                    if (garage == null) throw new ArgumentNullException(nameof(garage));
                    CarProgression.AwardGears(garage, outcome.carId, outcome.gears);
                    break;
            }
        }

        // Pay one owed prize and count it: resolve with PrizeSeed(profileSeed, chapter, prizesPaid + 1), apply, bump
        // prizesPaid. Returns a no-prize outcome (and changes nothing) when nothing is owed (PrizesOwed == 0) — a
        // Progression chapter already paid, every Replay completion already paid, or never completed.
        public static PrizeOutcome ClaimPrize(ChallengeEvent ev, ChallengeChapter chapter, IList<ChallengeRecord> records,
            CarCatalog catalog, IList<OwnedCar> garage, ICollection<string> altPaints, long profileSeed)
        {
            if (chapter == null) throw new ArgumentNullException(nameof(chapter));
            if (PrizesOwed(ev, chapter, records) <= 0) return new PrizeOutcome();
            var r = FindRecord(records, chapter.id);
            var o = ResolvePrize(chapter.prize, catalog, garage, altPaints, PrizeSeed(profileSeed, chapter.id, r.prizesPaid + 1));
            ApplyPrize(o, garage, altPaints);
            r.prizesPaid++;
            return o;
        }

        // Brings records read from an old or hand-edited save back inside the rules: no blank ids, one record per
        // chapter (merged), no negative counts, prizesPaid <= completions <= attempts.
        public static void Sanitise(List<ChallengeRecord> records)
        {
            if (records == null) return;
            var merged = new List<ChallengeRecord>();
            foreach (var r in records)
            {
                if (r == null || string.IsNullOrEmpty(r.chapterId)) continue;
                r.attempts = Math.Max(0, r.attempts);
                r.completions = Math.Max(0, r.completions);
                r.bestFinish = Math.Max(0, r.bestFinish);
                r.prizesPaid = Math.Max(0, r.prizesPaid);
                var into = FindRecord(merged, r.chapterId);
                if (into == null)
                {
                    merged.Add(r);
                    continue;
                }
                into.attempts += r.attempts;
                into.completions += r.completions;
                if (r.bestFinish > 0 && (into.bestFinish == 0 || r.bestFinish < into.bestFinish)) into.bestFinish = r.bestFinish;
                into.prizesPaid += r.prizesPaid;
            }
            foreach (var r in merged)
            {
                r.attempts = Math.Max(r.attempts, r.completions);
                r.prizesPaid = Math.Min(r.prizesPaid, r.completions);
            }
            records.Clear();
            records.AddRange(merged);
        }

        // PrizeFilter.Matches with the "no code = no prize" guard dropped: a Category prize's filter carries the
        // event's code, but be lenient if a hand-made one doesn't.
        static bool Matches(PrizeFilter f, CarDef car)
        {
            if (f == null || car == null) return false;
            if (!f.IsNone) return f.Matches(car);
            var copy = new PrizeFilter
            {
                code = "*", carsets = f.carsets, team = f.team, manufacturer = f.manufacturer,
                driverType = f.driverType, minRarity = f.minRarity, maxRarity = f.maxRarity,
            };
            return copy.Matches(car);
        }
    }
}
